const b = $input.first().json.body || {};
const ok = u => typeof u === 'string' && u.startsWith('https://res.cloudinary.com/yiq9yzmu/');
const urls = Array.isArray(b.urls) ? b.urls.filter(ok) : [];
const url = ok(b.url) ? b.url : '';
const s = v => (v === undefined || v === null) ? '' : String(v).slice(0, 500);
return [{ json: { source: 'render_result', job: s(b.job), task: s(b.task), engine: s(b.engine), voice: s(b.voice), url, urls, ok: !!(url || urls.length), commercial: b.commercial === true, fallback_reason: s(b.fallback_reason), credit_required: s(b.credit_required) } }];
